INSERT INTO `help_articles` VALUES (1,2,'账户注册','<div><span style=\"color: rgb(105, 105, 105);\">1<strong><span style=\"font-size: 16px;\">.</span></strong><span style=\"font-size: 16px;\"><span style=\"font-size: 11px;\">打开小米网，点击右上角</span></span>&ldquo;注册&rdquo;按钮&nbsp; &gt;&nbsp; 2.输入手机号和图片上的验证码&nbsp; &gt;&nbsp; 3.输入短信验证码，点击&ldquo;下一步&rdquo;按钮&nbsp; &gt;&nbsp;&nbsp; 4.按提示输入您的信息</span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 1.如图所示，打开小米网，点击右上角&ldquo;注册&rdquo;按钮；<br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670147810763_nHJKN.jpg\" style=\"height: 421px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n2.如图所示，输入手机号和图片上的验证码；<br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_1467114050733_lHkxm.jpg\" style=\"height: 507px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n3.如图所示，输入您手机短信中的验证码，点击&ldquo;下一步&rdquo;按钮；<br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14671140788612_iSfeD.jpg\" style=\"height: 482px; width: 861px;\" /><br />\r\n<br />\r\n4.按提示输入您的信息，设置密码，完成注册。</span></div>',1,'','2016-07-27 18:37:50','2016-07-27 18:37:50'),(2,2,'找回密码','<div><span style=\"color: rgb(105, 105, 105);\">如果您忘记了小米账号的密码，且账号中绑定的手机号还在使用，则可以通过一下两种方式找回密码：<br />\r\n<br />\r\n1. 进入</span><a href=\"https://i.xiaomi.com/\" target=\"https://mkm.kefu.mi.com/article/_blank\"><span style=\"color: rgb(255, 215, 0);\">https://i.xiaomi.com</span></a><span style=\"color: rgb(105, 105, 105);\">的登录页面选择&ldquo;忘记密码&rdquo;选项，自助找回密码。</span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 2.进入</span><a href=\"https://account.xiaomi.com/pass/serviceLogin\" target=\"https://mkm.kefu.mi.com/article/_blank\"><span style=\"color: rgb(255, 215, 0);\">http://www.mi.com</span></a><span style=\"color: rgb(105, 105, 105);\">的登录页面，输入您的账号后，点击下方的&ldquo;忘记密码&rdquo;选项，自助找回密码。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_1467016300344_IyQLm.jpg\" style=\"height: 622px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 如果您账号中绑定的手机号已经停止使用，则可以通过上述方式2点击&rdquo;忘记密码&ldquo;以后，通过人工审核的方式找回密码。</span></div>',1,'','2016-07-27 18:37:50','2016-07-27 18:37:50'),(3,2,'VIP认证','<div><span style=\"color: rgb(105, 105, 105);\">1.安装小米社区APP，进行VIP认证（目前暂时只支持安卓系统版本，IOS还需稍等片刻）；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670258020607_WpPFB.jpg\" style=\"height: 535px; width: 650px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.登陆小米社区，点击右下方的&ldquo;我的&rdquo;按钮，进入个人信息页面；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670258253123_qcrJa.jpg\" style=\"height: 1159px; width: 650px;\" /><br />\r\n<span style=\"color: rgb(105, 105, 105);\"> &nbsp;<br />\r\n3.点击&ldquo;等级&rdquo;按钮，进入VIP等级页面，完成升级任务，即可成为万众瞩目的VIP达人啦！</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670258606963_RGVuU.jpg\" style=\"height: 1156px; width: 650px;\" /><br />\r\n<br /></div>',1,'','2016-07-27 18:37:51','2016-07-27 18:37:51'),(4,3,'购买时间','<div><span style=\"color: rgb(105, 105, 105);\">登陆小米网，选择您所喜爱的产品，点击&ldquo;立刻购买&rdquo;之后，如下图所示，在商品详情页会有本产品的销售时间提示哦，预祝您买到自己心仪的产品。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670171011194_SwZid.jpg\" style=\"height: 562px; width: 861px;border: 1px solid #dfdfdf;\" /></div>',1,'','2016-07-27 18:37:51','2016-07-27 18:37:51'),(5,3,'产品参数','<div><span style=\"color: rgb(105, 105, 105);\">1.登陆小米网之后，在商品分类中选择您所喜爱的产品，点击进入；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670177608931_KwOsz.jpg\" style=\"height: 223px; width: 861px;\" /><br />\r\n<span style=\"color: rgb(105, 105, 105);\">&nbsp;<br />\r\n2.点击产品详情页面右上方的&ldquo;参数&rdquo;按钮，进入参数介绍页面；<br />\r\n&nbsp;</span><br />\r\n<img alt=\"\" src=\"//i3.mifile.cn/a4/cms_1467172361124_gYXVN.jpg\" style=\"height: 596px; width: 861px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.近距离对话，由此开始。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670178378252_LxAOC.jpg\" style=\"height: 563px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br /></div>',1,'','2016-07-27 18:37:51','2016-07-27 18:37:51'),(6,3,'包邮政策','<div><div class=\"xm-exchange-content mail\" data-class=\"mail\">\r\n<div class=\"text mail\">\r\n<div class=\"exchange_bd\">\r\n<table>\r\n<thead>\r\n	<tr>\r\n	<th rowspan=\"2\" width=\"20%\">\r\n		商品类别</th>\r\n	<th colspan=\"2\">\r\n		商品类别</th>\r\n	<th colspan=\"2\" rowspan=\"2\" width=\"35%\">\r\n		配送方式</th>\r\n	</tr>\r\n	<tr>\r\n	<th>\r\n		150元以下／单</th>\r\n	<th>\r\n		150元以上／单</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n	<tr>\r\n	<th>\r\n		手机，配件等商品</th>\r\n	<td>10元／单</td>\r\n	<td>免费送货</td>\r\n	<td>快递送货上门</td>\r\n	</tr>\r\n	<tr>\r\n	<th>\r\n		小米电视</th>\r\n	<td>－</td>\r\n	<td>送货上门</td>\r\n	<td>单品配送费100元<br />\r\n	小米电视2 家庭影院版 配送费150元<br />\r\n	小米电视3 配送费200元<br />\r\n	<a href=\"http://bbs.xiaomi.cn/thread/index/tid/11435790\" target=\"_blank\">了解详情&gt;</a></td>\r\n	</tr>\r\n	<tr>\r\n	<th class=\"line\">\r\n		小米净水器</th>\r\n	<td class=\"line\">－</td>\r\n	<td class=\"line\">送货上门</td>\r\n	<td class=\"line\">单品配送费30元<br />\r\n	<a href=\"http://bbs.xiaomi.cn/thread/index/tid/11515616\" target=\"_blank\">了解详情&gt;</a></td>\r\n	</tr>\r\n	<tr>\r\n	<th>\r\n		小米体重秤</th>\r\n	<td>－</td>\r\n	<td>送货上门</td>\r\n	<td>单品配送费15元<br />\r\n	同单第二件产品累计运费<br />\r\n	<a href=\"http://bbs.xiaomi.cn/thread-11211492-1-1.html\" target=\"_blank\">了解详情&gt;</a></td>\r\n	</tr>\r\n	<tr>\r\n	<th>\r\n		小米电视主机<br />\r\n		小米低音炮</th>\r\n	<td>－</td>\r\n	<td>送货上门</td>\r\n	<td>单品配送费50元<br />\r\n	同单第二件产品累计运费</td>\r\n	</tr>\r\n</tbody>\r\n</table></div>',1,'','2016-07-27 18:37:51','2016-07-27 18:37:51'),(7,3,'下单及支付时效','<div><span style=\"color: rgb(105, 105, 105);\">1.加入购物车的产品，通常情况下下单时效为2小时，过期后订单将会自动关闭；活动期间下单时效以活动细则为准。<br />\r\n&nbsp;</span><br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670202336081_KQWVO.jpg\" style=\"height: 587px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> <span style=\"font-size: 14px;\"><strong> 备注：</strong></span></span><br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 在您加入购物车之后，有下单时效的产品，页面上会有相应的时间提示，请注意查看，不要错过哦。<br />\r\n<br />\r\n<br />\r\n2.在线支付的订单通常情况下支付时效为48小时，过期后订单将会自动关闭；活动期间支付时效以活动细则为准。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670202910123_SPtjK.jpg\" style=\"height: 410px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<strong><span style=\"font-size: 14px;\"><span style=\"color: rgb(105, 105, 105);\"> 备注：</span></span></strong><br />\r\n<p><span style=\"color: rgb(105, 105, 105);\">在您提交订单之后页面上会有相应的时间提示，请注意查看，不要错过支付时效哦。</span></p></div>',1,'','2016-07-27 18:37:52','2016-07-27 18:37:52'),(8,3,'发货时效','<div><p><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，小米网将参照支付顺序在7天内发出，F码购买的商品，无法保证均可在7天内发出（活动期间以活动公告为准），具体的呢，您可以查看您购买的商品的订单详情中就会看到预计的发货周期噢，最快情况下我们的商品会在24小时内出库的，受客观物流因素影响，可能会有部分延迟，请您耐心等待。</span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">注：快递配送可能会因为交通、天气等原因有所延误，建议您登陆小米官网/小米商城，到订单详情或者快递公司官网关注配送进度。</span></p></div>',1,'','2016-07-27 18:37:52','2016-07-27 18:37:52'),(9,3,'物流及配送','<div><div class=\"delivery\">\r\n<p>小米网购物采用第三方快递配送。<br />\r\n用户可以在我的订单里查询分配的订单的快递，从而及时查阅物流信息。<br />\r\n用户可以登录第三方快递公司相应网站：</p>\r\n<div class=\"delivery-section\">\r\n<div class=\"section01 section\">\r\n<h3>第三方配送公司</h3>\r\n<p>登录相关物流网站，输入相应单号，即可查询货物配送状态，如需其他疑问请咨询小米官方客服人员。</p>\r\n<div class=\"delivery-classify clearfix\">\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.rufengda.com/\" target=\"_blank\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_rfd.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.rufengda.com/\" target=\"_blank\">前往如风达官网</a><i class=\"iconfont\"></i></dd>\r\n</dl>\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.sf-express.com/cn/sc/\" target=\"_blank\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_sf.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.sf-express.com/cn/sc/\" target=\"_blank\">前往顺丰速递官网</a><i class=\"iconfont\"></i></dd>\r\n</dl>\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.sto-express.com.cn\" target=\"\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_st.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.sto-express.com.cn\" target=\"_blank\">前往申通官网</a><i class=\"iconfont\"></i></dd>\r\n</dl>\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.yto.net.cn\" target=\"_blank\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_yt.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.yto.net.cn\" target=\"_blank\">前往圆通官网</a><i class=\"iconfont\"></i></dd>\r\n</dl>\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.ems.com.cn\" target=\"_blank\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_ems.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.ems.com.cn\" target=\"_blank\">前往ems官网</a><i class=\"iconfont\"></i></dd>\r\n</dl>\r\n<dl>\r\n	<dt>\r\n		<a href=\"http://www.yundaex.com/\" target=\"_blank\"> <img src=\"//s01.mifile.cn/i/service/other/helpCenter/delivery_yd.jpg\" /> </a></dt>\r\n	<dd>\r\n		<a href=\"http://www.yundaex.com/\" target=\"_blank\">前往韵达官网</a><i class=\"iconfont\"></i></dd>\r\n</dl></div>',1,'','2016-07-27 18:37:52','2016-07-27 18:37:52'),(10,3,'支付方式','<div><span style=\"color: rgb(105, 105, 105);\">小米网提供支付宝、财付通，手机支付等第三方平台支付，同时支持国内二十多家主流银行机构的储蓄卡、信用卡的网上付款。暂时不支持货到付款的支付方式，您购买的时候一定要注意哦，以免影响您的正常收货。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670210981991_uaJhQ.jpg\" style=\"height: 601px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<h4><span style=\"color: rgb(105, 105, 105);\">备注：</span></h4>\r\n<span style=\"color: rgb(105, 105, 105);\">小米网所支持的银行机构可能会有变动，以实际支付页面的信息为准。<br />\r\n小米网暂时不支持货到付款业务，所以大家买到货到付款的产品有可能是假货，要提高警惕哦。</span><br />\r\n&nbsp;<br /></div>',1,'','2016-07-27 18:37:52','2016-07-27 18:37:52'),(11,4,'查询发货进度','<div><span style=\"color: rgb(105, 105, 105);\">生成订单后，您可随时登录小米网，打开&ldquo;我的订单&rdquo;，跟踪查看订单的进展情况。<br />\r\n<br />\r\n1.登录小米网，点击&ldquo;我的订单&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670212793144_wvhsl.jpg\" style=\"height: 420px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.在订单列表中，找到您要查询的订单，点击&ldquo;订单详情&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670213014964_aivpc.jpg\" style=\"height: 537px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.进入订单详情页，即可了解具体发货信息。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_1467021319918_gOaiF.jpg\" style=\"height: 577px; width: 861px;border: 1px solid #dfdfdf;\" /><span style=\"color: rgb(105, 105, 105);\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><br /></div>',1,'','2016-07-27 18:37:53','2016-07-27 18:37:53'),(12,4,'修改订单信息','<div><span style=\"color: rgb(105, 105, 105);\">在这个拼手速的时代，只要您够快，能拼得过我们仓库的配货速度，就可以自行在前端修改信息哦，在有效时间内，您可以自行修改收货地址与送货时间，悄悄告诉你，这个时间很短，您一定要快、准、狠。<br />\r\n<br />\r\n1.登录小米网，点击&ldquo;我的订单&rdquo;，在订单列表中找到您要修改的订单，点击&ldquo;修改按钮&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14671796875065_sqpEG.jpg\" style=\"height: 717px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.输入短信中的提示的6位数字验证码，点击&ldquo;确认&rdquo;按钮；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14671156683567_ZzDeH.jpg\" style=\"height: 598px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.依次填写您需要修改的信息，确认无误后，点击&ldquo;确认&rdquo;按钮，修改成功。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670218740157_LOlux.jpg\" style=\"height: 595px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">一不留神订单已经流转到下一个状态了肿么办？没关系哦，不要惊慌，火速拿起你的手机，拨打4001005678客服热线，提供您的订单信息，让我们的工作人员帮您确认，如果可以会尽量帮助您修改哦。</span></div>',1,'','2016-07-27 18:37:53','2016-07-27 18:37:53'),(13,4,'取消订单','<div><span style=\"color: rgb(105, 105, 105);\">1.登录小米网，点击&ldquo;我的订单&rdquo;，在订单列表中找到您要取消的订单，点击&ldquo;申请退款&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670220794135_oeNRI.jpg\" style=\"height: 651px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.选择并填写申请退款的原因，点击&ldquo;获取验证码&rdquo;按钮，并正确填写，确认无误点击&ldquo;确认&rdquo;按钮，申请成功。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670222294612_dEcov.jpg\" style=\"height: 599px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br /></div>',1,'','2016-07-27 18:37:53','2016-07-27 18:37:53'),(14,4,'查询物流信息','<div><span style=\"color: rgb(105, 105, 105);\">生成订单后，您可随时登录小米网，打开&ldquo;我的订单&rdquo;，跟踪查看订单的进展情况。<br />\r\n<br />\r\n1.登录小米网，点击&ldquo;我的订单&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670222904133_rzmqu.jpg\" style=\"height: 420px; width: 861px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.在订单列表中，找到您要查询的订单，点击&ldquo;订单详情&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_146702232337_gGtAq.jpg\" style=\"height: 537px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.进入订单详情页，点击&ldquo;展开物流详情&rdquo;按钮，即可了解具体物流信息。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_1467022472503_EaMvH.jpg\" style=\"height: 569px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br /></div>',1,'','2016-07-27 18:37:53','2016-07-27 18:37:53'),(15,4,'查询订单信息','<div><span style=\"color: rgb(105, 105, 105);\">生成订单后，您可随时登录小米网，打开&ldquo;我的订单&rdquo;，点击订单详情，即可查看订单信息。<br />\r\n<br />\r\n1.登录小米网，点击&ldquo;我的订单&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670227323016_mhIET.jpg\" style=\"height: 420px; width: 861px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.在订单列表中，找到您要查询的订单，点击&ldquo;订单详情&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670227747293_WTLlb.jpg\" style=\"height: 537px; width: 861px;border: 1px solid #dfdfdf;\" /></div>',1,'','2016-07-27 18:37:54','2016-07-27 18:37:54'),(16,4,'订单拆分与合并','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，目前小米网不支持合并订单/拆分订单的，建议放在购物车中一起下单或分批加入购物车后下单呢。</span></div>',1,'','2016-07-27 18:37:54','2016-07-27 18:37:54'),(17,4,'优惠券查询','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，您在登陆小米网的状态下，点击&ldquo;个人中心&rdquo;---&ldquo;优惠券&rdquo;即可查询您当前拥有的优惠券喽，优惠券都会清楚的标注使用时效，一定要记得使用喔，过期作废就可惜了呢。<br />\r\n<br />\r\n1.登录小米网，点击&ldquo;个人中心&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14671799159298_UXWyc.jpg\" style=\"height: 420px; width: 861px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.个人中心栏目下的&ldquo;优惠券&rdquo;按钮；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670228832517_MjAqO.jpg\" style=\"height: 510px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.即可查看您现有的优惠券详情。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670229310661_ocbwA.jpg\" style=\"height: 429px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br /></div>',1,'','2016-07-27 18:37:54','2016-07-27 18:37:54'),(18,5,'如何刷机','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，刷机最早是发烧友间DIY的一种方式，刷机充满了很多不稳定因素，如您没有成熟的刷机经验，我们是不建议您进行操作的，刷机有风险可能还会丢 失手机中的重要数据。如果您的手机出现问题需要刷机建议您到授权维修网点让工程师帮助您处理。<br />\r\n<br />\r\n当然，如果聪明的米粉们想要自己尝试，我们这边也准备了简单的刷机教程</span><a href=\"http://www.miui.com/shuaji.html\" target=\"https://support.kefu.mi.com/_blank\"><span style=\"color: rgb(255, 140, 0);\">根据机型选择对应的刷机教程</span></a><span style=\"color: rgb(105, 105, 105);\">，若您需要下载刷机包也可以</span><a href=\"http://www.miui.com/download.html\" target=\"https://support.kefu.mi.com/_blank\"><span style=\"color: rgb(255, 140, 0);\">点击这里下载系统包</span></a><span style=\"color: rgb(105, 105, 105);\">，点击这里请在有经验的米粉监护下进行操作，如果较为复杂建议您联系在线客服的小伙伴们帮助您处理啦。<br />\r\n<br />\r\n注：<br />\r\n<br />\r\n为提高用户数据的安全性、保证查找手机功能的可靠性，防止黄牛批量刷三方ROM导致用户信息泄露或其他系统问题，小米后期机型加入BL锁。加入BL锁的机型刷机需注意如下几点：<br />\r\n<br />\r\n1、加入BL锁机型可以进行联网验证的刷机，无法进行离线刷机；<br />\r\n2、有BL锁且未解锁的机型可进行的刷机方式包括：OTA升级、下载最新版本完整包、手动选择安装包、小米助手OTA升级、小米助手恢复模式刷机（卡刷）、小米助手线刷（暂不可使用）；<br />\r\n3、有BL锁机型解锁后可进行的刷机方式包括：OTA升级、下载最新版本完整包、手动选择安装包、小米助手OTA升级、小米助手恢复模式刷机（卡刷）、小米助手线刷、Miflash线刷；<br />\r\n4、有BL锁机型，无论是否解锁均无法进入Recovery模式（也就是无法实现Rcovery模式的清除数据和卡刷操作）</span></div>',1,'','2016-07-27 18:37:54','2016-07-27 18:37:54'),(19,5,'无法开机','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，小米手机无故死机卡机：<br />\r\n<br />\r\n1.您是否尝试过更换电池试试呢？（人家说的是可以拆卸电池的机子）<br />\r\n<br />\r\n2.是否因电池电量低而自动关机？或手机长时间处于零电量状态？电池电量过低自动关机，电池会进入休眠状态。需要充电半小时以上即可开机，可以更换其他的充电器或者数据线充电尝试，看能否开机。<br />\r\n<br />\r\n3.使用某软件时死机，请先等待一段时间，一般会出现&ldquo;xxx程序未响应，是否关闭&rdquo;这样的提示，可以点击关闭后重新打开使用；<br />\r\n<br />\r\n4.如果手机卡住很久没有反应，先尝试点击手机的HOME键，如果可以返回桌面，可以长按HOME键调出任务管理将卡死的程序关闭，重新打开使用；<br />\r\n<br />\r\n5.如果手机无任何反应，米2及米3、米4、小米Note系列，可以长按电源键10s以上进行强制重启，其它系列可以拔掉电池重新开机。Root权限对系统影响很大的，若您开启过Root，那就关掉他试试吧。<br />\r\n<br />\r\n6.尝试是否可以进入Recovery模式，若可以进入，选择&ldquo;清除用户数据&rdquo;后再进入系统，会清除联系人、短信、程序等数据，操作之前一定要对数据进行备份哦。<br />\r\n<br />\r\n7.如果是在刷机之后导致无法开机，建议重新尝试刷机，如仍无法恢复正常建议您到附近授权维修网点让工程师帮助您操作一下就可以恢复正常。</span></div>',1,'','2016-07-27 18:37:55','2016-07-27 18:37:55'),(20,5,'无法解锁','<div><span style=\"font-size: 16px;\"><span style=\"color: rgb(169, 169, 169);\"><strong>若您遇到您的手机使用指纹解锁/指纹识别失效时，请您尝试以下方法解决：</strong></span></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"><span style=\"color: rgb(105, 105, 105);\">① </span>清理指纹识别器<br />\r\n<span style=\"color: rgb(105, 105, 105);\">② </span>手指是否有液体（水渍、汗液）<br />\r\n<span style=\"color: rgb(105, 105, 105);\">③ </span>手指过于干燥，导致无法准确识别<br />\r\n<span style=\"color: rgb(105, 105, 105);\">④ </span>指纹识别器被遮挡或未完全露出<br />\r\n若上述方法均无法解决，建议您重新录入指纹尝试，录入时请使用平时最常用的握姿，或尝试恢复出厂设置。<br />\r\n<br />\r\n注意:<br />\r\n此操作会清除手机数据内容,请谨慎操作</span><br />\r\n<br />\r\n<span style=\"font-size: 16px;\"><strong><span style=\"color: rgb(169, 169, 169);\">若您在手机上设定了锁屏密码，但是忘记密码请按照如下方法解决：</span></strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(128, 128, 128);\"><strong><strong>MIUI 7开发版6.3.10之后<span id=\"kmhighlighter\">的</span>版本</strong></strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">一、因为清除锁屏密码会造成用户数据<span id=\"kmhighlighter\">的</span>丢失，所以在操作前一定要记得将数据进行备份：<br />\r\n<br />\r\n1、&nbsp;如开启了云服务可在<a href=\"https://i.mi.com/\" target=\"_blank\">https://i.mi.com/</a>确认数据是否同步到云端；<br />\r\n2、&nbsp;安卓版本在6.0以下<span id=\"kmhighlighter\">的</span>手机可尝试连接小米手机助手备份数据。<br />\r\n<br />\r\n二、备份数据后可选择以下方法中<span id=\"kmhighlighter\">的</span>一种清除锁屏密码：<br />\r\n<br />\r\n1、无BL锁<span id=\"kmhighlighter\">的</span>机型<br />\r\n<br />\r\n① Recovery模式清除用户数据；<br />\r\n② 支持线刷<span id=\"kmhighlighter\">的</span>机型进入Fastboot连接小米手机助手或者Miflash线刷（选择清除所有数据）；<br />\r\n③ 如果手机登陆了小米账号并开启了&ldquo;查找手机&rdquo;可登陆<a href=\"https://i.mi.com/\" target=\"_blank\">https://i.mi.com/</a>进入查找设备界面选择&ldquo;擦除&rdquo;手机。<br />\r\n<br />\r\n2、有BL锁<span id=\"kmhighlighter\">的</span>机型<br />\r\n<br />\r\n① 安卓版本在6.0以下<span id=\"kmhighlighter\">的</span>手机在关机状态下使用&rdquo;电源键+音量上&rdquo;进入恢复模式连接小米手机助手刷机；<br />\r\n② 如果手机登陆了小米账号并开启了&ldquo;查找手机&rdquo;可登陆<a href=\"https://i.mi.com/\" target=\"_blank\">https://i.mi.com/</a>进入查找设备界面选择&ldquo;擦除&rdquo;手机；<br />\r\n③ 如果愿意通过线刷<span id=\"kmhighlighter\">的</span>方式清除<span id=\"kmhighlighter\">锁</span><span id=\"kmhighlighter\">屏</span><span id=\"kmhighlighter\">密码</span>，可以在<a href=\"http://www.miui.com/unlock/\" target=\"_blank\">http://www.miui.com/unlock/</a>申请<span id=\"kmhighlighter\">解锁</span>权限；<br />\r\n④ 若以上2种方法都<span id=\"kmhighlighter\">无法</span>清除锁屏密码，就需要麻烦您到当地售后网点处理。</span><br />\r\n<br />\r\n<span style=\"color: rgb(128, 128, 128);\"><strong>MIUI 7开发版6.3.10之前<span id=\"kmhighlighter\">的</span>版本</strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">1、如果您绑定了谷歌账号或者小米账号，可以在锁屏界面多次错误密码后会出现忘记密码<span id=\"kmhighlighter\">的</span>选项。点击后输入绑定<span id=\"kmhighlighter\">的</span>谷歌/小米账号密码<span id=\"kmhighlighter\">解锁</span>即可，需要注意的是使用谷歌/小米账号<span id=\"kmhighlighter\">解锁</span>需要保持手机联网。<br />\r\n2、如果您没有绑定过谷歌/小米账号，只能进入Recovery清除用户数据。（无BL锁机型，有BL锁机型需连接小米手机助手进入恢复模式清除数据）<br />\r\n<br />\r\n注意：<br />\r\n此操作会清空您<span id=\"kmhighlighter\">的</span>短信、联系人、通话记录、账号等个人信息，请谨慎操作。</span></div>',1,'','2016-07-27 18:37:55','2016-07-27 18:37:55'),(21,5,'信号问题','<div><span style=\"color: rgb(169, 169, 169);\"><strong><span style=\"font-size: 16px;\">1.小米手机无信号怎么办？</span></strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，手机无信号可以按照以下步骤尝试解决：<br />\r\n<br />\r\n1.是否正确的插入了SIM卡，重新插拔尝试；<br />\r\n2.是否插入了错误的SIM卡，如标准版插入电信SIM卡，如电信合约机插入移动卡等；<br />\r\n3.在拨号界面输入*#*#64663#*#*进入硬件检测模式，打开第二项SIM卡测试，若SIM状态正常，则转至步骤5，若状态未知则转至步骤4；<br />\r\n4.尝试更换一张其他的SIM卡，若硬件检测中状态依旧为未知，则建议至维修点进行检测；若检测状态为正常，则建议至运营商更换一张SIM卡（SIM卡可能老化）。<br />\r\n5.网络类型是否正确，运营商选择是否为自动（联通选3G优先、移动选仅2G、电信选自动）<br />\r\n6.若非电信版手机的网络类型为CDMA自动，则需在手机信息（*#*#4636#*#*）中将网络类型改为&quot;WCDMA Preferred&quot;即可。</span><br />\r\n<br />\r\n<br />\r\n<span style=\"color: rgb(169, 169, 169);\"><strong><span style=\"font-size: 16px;\">2.小米手机信号弱怎么办？</span></strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，如果手机信号不佳，可以尝试以下步骤：<br />\r\n<br />\r\n1.首先根据您所使用的运营商来选择合理的网络类型设置；<br />\r\n2.判定是否为运营商信号的问题(尝试更换一张同运营同网的SIM卡)，查看周围同运营商网络的手机是否也有信号不佳的情况；<br />\r\n3.升级到最新版本的MIUI系统；<br />\r\n4.备份好手机数据后，恢复出厂设置来排除软件带来的影响；<br />\r\n5.到维修网点检测是否是硬件故障。 </span></div>',1,'','2016-07-27 18:37:55','2016-07-27 18:37:55'),(22,5,'通话时黑屏无法亮起','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，如果您遇到通话中黑屏且无法自动亮起的问题，可以按照以下步骤进行排查：<br />\r\n<br />\r\n1.您是否用了非官方的贴膜或者原厂包装膜没有撕掉。<br />\r\n<br />\r\n2.是否有异物（一些手机贴等）挡住了您的距离感应器，即您手机屏幕上方。<br />\r\n<br />\r\n3.尝试校准距离感应器，首先拨号界面输入&ldquo;*#*#64663#*#*&rdquo;，选择距离感应器测试，不要遮挡屏幕上方，点击开始校准，等待3秒左右即可通过。<br />\r\n<br />\r\n如果以上方法都没有解决您的问题，建议您到维修网点检测一下，查看您的距离感应器硬件是否出现故障。</span></div>',1,'','2016-07-27 18:37:55','2016-07-27 18:37:55'),(23,5,'无法充电','<div><span style=\"color: rgb(105, 105, 105);\">1、如果插上充电器，在没有执行任何操作的前提下，手机发热，建议您拔下充电器，前往小米之家或授权维修中心检测。<br />\r\n<br />\r\n2、如果是关机后插上充电器红色LED灯闪烁的情况，请在充电时长达到15-30分钟后尝试开机。<br />\r\n<br />\r\n3、开机状态下插上充电器没有反应（LED灯不亮、电量显示出没有反应）的情况，如有条件请更换标配充电器或者原装电池尝试解决，也可以使用不同产品型号相同输出功率的充电器，但只是作为检测原装充电器是否存在问题的一个方法，不建议经常使用，如果是充电器或电池问题建议联系售后更换来解决。针对无法拆卸电池的小米产品（小米手机3、小米手机4、小米Note、小米平板）可以跳过更换电池判断方法。<br />\r\n<br />\r\n4、如果插上充电器手机LED显示可以亮起、电量显示处也显示在充电，但是电量进度没有变化，可以线刷尝试。<br />\r\n<br />\r\n5、以上方法都无法解决问题，建议您去到当地小米之家或授权维修中心检测和维修。 </span></div>',1,'','2016-07-27 18:37:55','2016-07-27 18:37:55'),(24,6,'售后申请','<div><span style=\"color: rgb(211, 211, 211);\"><strong><span style=\"font-size: 18px;\">一、在小米网购买的产品</span></strong></span><br />\r\n<br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 1.登录小米网，点击&ldquo;我的订单&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670232138467_DVhkt.jpg\" style=\"height: 420px; width: 861px;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">2.在订单列表中，找到您要申请售后的订单，点击&ldquo;申请售后&rdquo;；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14671144233561_OWyck.jpg\" style=\"height: 537px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">3.进入<span style=\"display: none;\">&nbsp;</span>售后详情页之后</span><a href=\"http://service.order.mi.com/apply/fill\"><span style=\"display: none;\">&nbsp;</span></a><span style=\"color: rgb(105, 105, 105);\">，选择您所需要进行售后的产品和服务，点击售后服务按钮，会出现该产品售后的详情页面；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14673417842426_izSPx.jpg\" style=\"height: 603px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">4.点击按钮选择您需要的服务项目；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_1467341921933_oPfVU.jpg\" style=\"height: 564px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">5.填写您的产品的问题类型，如果列表中没有您的产品问题，可以点击其他按钮，在问题描述中说明您遇到的问题，然后选择您需要的服务方式，点击下一步按钮；</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14673420093403_pJeCH.jpg\" style=\"height: 804px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">6.选择您的取件方式，并核对您的收获信息，确认无误后，点击下一步按钮，完成申请。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14673422453822_FxGtO.jpg\" style=\"height: 774px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n7.完成申请，请耐心等待我们的客服同学与您确认哦。<br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14673437755787_coUJs.jpg\" style=\"height: 329px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<span style=\"color: rgb(211, 211, 211);\"><span style=\"font-size: 18px;\">二、</span></span><span style=\"color: rgb(211, 211, 211); font-weight: bold; font-size: 18px;\">在其他渠道购买的产品</span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">在</span><a href=\"http://service.order.mi.com/apply/fill\"><span style=\"color: rgb(255, 140, 0);\">售后详情页</span></a><span style=\"color: rgb(105, 105, 105);\">，选择对应的分类，填写串号，上传发票，系统会根据您的发票日期判定，您是否可以进行换货。如果您的发票丢失可选择 &ldquo;无发票 &rdquo;，选择无发票会按照出厂日期保修，仅支持维修服务。</span><br />\r\n<br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14673455283752_VtjGk.jpg\" style=\"height: 891px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"> 注：<br />\r\n<br />\r\n因质量问题发生的退换货情况，由小米公司承担退换货物流费用，需要您先进行垫付，小米公司凭您的付费发票进行报销，报销金额最高上限15 元/单。（提示：平邮处理时间大概需要一个月左右，为了节省您的售后服务时间建议选择快递方式邮寄。）<br />\r\n<br />\r\n退货用户，我们在货品验收无误后，一周内为您办理退款，在线支付的用户会将款项原路返还退回至您的支付账号中。</span><br />\r\n<br />\r\n<br />\r\n<br /></div>',1,'','2016-07-27 18:37:56','2016-07-27 18:37:56'),(25,6,'售后进度查询','<div><span style=\"color: rgb(169, 169, 169);\"><span style=\"font-size: 16px;\"><strong>如果你是一个勤快的孩纸：</strong></span></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">您可可以登陆小米网，按照下面这个路线前进，就能找到你要的答案，我们为您准备好了传送门：</span><a href=\"http://service.order.mi.com/cservice/repairinfoEx\" target=\"https://support.kefu.mi.com/\"><span style=\"color: rgb(255, 140, 0);\">走起</span></a><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">如您申请的设备没有IMEI或SN，且是在官网申请售后的，打开我的订单&mdash;&mdash;售后服务栏下的我的服务单，查询售后进度。</span><br />\r\n<br />\r\n<br />\r\n<span style=\"color: rgb(169, 169, 169);\"><span style=\"font-size: 16px;\"><strong>如果你是个爱撒娇的孩纸：</strong></span></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">你可以来访在线\\热线客服，提供联系电话/订单号由小米客服为您查询哦。</span></div>',1,'','2016-07-27 18:37:57','2016-07-27 18:37:57'),(26,6,'快递费报销','<div><span style=\"color: rgb(105, 105, 105);\">商品发生有质量问题的退换修时，经我们核实您的商品符合快递费报销的标准，我们会为您报销至多不超过15元的快递费，我们会为您发送领取报销快递费的短信，您可以根据短信直接到快递报销页面中申请领取，审核通过后会在7个工作日内到账。我们为您准备好了传送门：</span><a href=\"http://service.order.mi.com/user/compensate\" target=\"https://support.kefu.mi.com/_blank\"><span style=\"color: rgb(255, 140, 0);\">走起</span></a></div>',1,'','2016-07-27 18:37:57','2016-07-27 18:37:57'),(27,6,'返厂邮寄注意事项','<div><span style=\"font-size: 16px;\"><span style=\"color: rgb(169, 169, 169);\"><strong>1.不要寄平邮和到付，不要寄平邮和到付，不要寄平邮和到付，重要事情说三遍</strong></span></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">由于平邮、货到付款的取货周期长，我们为了不影响您的售后流程正常进行，建议您使用除平邮及货到付款以外的快递方式邮寄商品，给您带来不便请谅解。</span><br />\r\n<br />\r\n<span style=\"font-size: 16px;\"><span style=\"color: rgb(169, 169, 169);\"><strong>2.符合快递费报销标准的，至多可以报销15元快递费</strong></span></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">同时，如您的商品符合快递费报销的标准，我们会为您报销至多不超过15元的快递费，所以不要忘记向快递公司要发票哦。</span></div>',1,'','2016-07-27 18:37:57','2016-07-27 18:37:57'),(28,6,'发票修改咨询','<div><span style=\"color: rgb(105, 105, 105);\">您好，目前在官网购买的商品默认是开具电子发票，若是您需要纸质发票，请在下单时手动选择普通发票，选择后不能更改，请谨慎操作。</span></div>',1,'','2016-07-27 18:37:57','2016-07-27 18:37:57'),(29,6,'维修网点信息','<div><span style=\"color: rgb(105, 105, 105);\">网点在哪里呀？网点在哪里？网点在那最近的街角里&hellip;&hellip;</span><a href=\"http://www.mi.com/c/service/poststation/#province=2\"><span style=\"color: rgb(255, 140, 0);\">戳我</span></a><span style=\"color: rgb(105, 105, 105);\">为您查询最近的维修网点信息。<br />\r\n<br />\r\n温馨提示：<br />\r\n<br />\r\n小米电视的售后，请您拨打400-100-5678或者来访在线客服，选择电视分类进行售后处理。<br />\r\n小米授权维修网点上班时间及您需要咨询的相关事宜，您可以联系附近的维修网点进行咨询哦。</span></div>',1,'','2016-07-27 18:37:57','2016-07-27 18:37:57'),(30,6,'手机类产品售后政策','<div><div class=\"exchange_bd\" style=\"padding-bottom: 70px; color: rgb(117, 117, 117); font-family: \'Helvetica Neue\', Helvetica, Arial, \'Microsoft Yahei\', \'Hiragino Sans GB\', \'Heiti SC\', \'WenQuanYi Micro Hei\', sans-serif; font-size: 14px; line-height: 21px; white-space: normal; background-color: rgb(255, 255, 255);\">\r\n<p style=\"margin: 0px;\">小米公司承诺符合以下情况，由产品售出之日（以实际收货日期为准）起&nbsp;<strong style=\"color: rgb(66, 66, 66);\">7日内无理由退货，质量问题15日内包换，一年质保</strong>，您可在线提交订单申请或者与小米客服中心联系办理退换货事宜。</p></div>',1,'','2016-07-27 18:37:58','2016-07-27 18:37:58'),(31,7,'挂架安装','<div><span style=\"color: rgb(105, 105, 105);\">小米电视支持挂架安装服务，但目前小米电视标配中不包含挂架配饰，如您需要壁挂的配件，可以在购买电视的时候，选择预约挂架安装服务，也可以拨打4001005678选择电视业务，进行购买的咨询的哦，未来小米商城推出更多周边的产品，以供大家选择，以下是挂架相关问题汇总：</span><br />\r\n<br />\r\n<h5><span style=\"color: rgb(105, 105, 105);\">收费标准：</span></h5>\r\n<img src=\"//i3.mifile.cn/a4/cms_14670243277447_VtpoP.jpg\" style=\"height: 399px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\"><strong>备注：</strong><br />\r\n</span>\r\n<ul>\r\n<li><span style=\"color: rgb(105, 105, 105);\">以上费用标准仅指人工费,不包含上门费、挂架费和特殊墙体辅料费。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">挂架安装需要对施工墙体进行评估,并由工程师确认是否满足施工条件,消费者可致电小米客服热线4001005678进行报装,会有授权工程师与您预约上门安装时间。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">往返距离大于30公里的上门服务属于远程服务,对超出30公里的路程部分收取上门费,收费标准为1元/公里。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">采用非小米原装挂架或自行安装造成的事故,小米公司不承担任何法律责任。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">对于同次上门电视、主机、条形音箱同时安装,只结算电视安装费,不累计结算。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">移机包含:座装移座装、座装移挂装、挂装移座装、挂装移挂装。</span></li>\r\n</ul>\r\n<h5><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">挂架价格：</span></h5>\r\n<img src=\"//i3.mifile.cn/a4/cms_1467024498021_Clkef.jpg\" style=\"height: 152px; width: 861px;\" /><br />\r\n<br />\r\n<strong><span style=\"color: rgb(105, 105, 105);\">注意事项：</span></strong><br />\r\n<ul>\r\n<li><span style=\"color: rgb(105, 105, 105);\">普通砖墙、混凝土墙钻，钻孔时需要专业的技术及器械，建议专业人员安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">空心砖墙、板墙、装饰墙、石膏墙、木墙等，容易出现跌落损毁，建议专业人员安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">墙内存在用电布线的砖墙，钻孔时存在电击隐患，建议专业人员安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">大理石墙、玻璃墙等，钻孔时容易造成墙面破损，建议专业人员安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">接近水源和湿度较高的环境不适宜安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">阳光直射或其他强光直射的环境不适宜安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">易震动和跌落的地方不适宜安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">圆形柱面墙体不适宜安装；</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">切勿在电视机身上悬挂重物；</span></li>\r\n</ul></div>',1,'','2016-07-27 18:37:58','2016-07-27 18:37:58'),(32,7,'以旧换新','<div><span style=\"color: rgb(105, 105, 105);\">每个人的手里都有那么几部手机，送人不合适、闲置舍不得、丢弃不环保，真可谓&ldquo;愁死个人咧&rdquo;。现在小米公司与爱回收网合作推出的以旧换新服务，为您的手机寻找了一个合适的归宿，您可以用自己的旧手机交换手机换新券。手机换新券可以在小米官网上购买新机时抵扣相应金额，小米公司的大部分手机产品（个别机型暂不支持此服务）皆在回收范围之内 ，如果您有闲置不用的手机，这是推陈出新的好机会哦，更多介绍，</span><a href=\"http://huanxin.mi.com/\" target=\"https://support.kefu.mi.com/_blank\"><span style=\"color: rgb(255, 140, 0);\">点击这里</span></a><span style=\"color: rgb(105, 105, 105);\">前往以旧换新页面查看。</span></div>',1,'','2016-07-27 18:37:58','2016-07-27 18:37:58'),(33,7,'意外保障服务','<div><span style=\"color: rgb(105, 105, 105);\">哦卖噶！刚买的手机掉地上摔碎了&hellip;&hellip;<br />\r\n天了噜！手机和衣服一起泡水里了&hellip;&hellip;<br />\r\nHelp me！手机掉厕所里了&hellip;&hellip;<br />\r\n你是不是也有这样悲催的时候？维修费用惊人，扔了又觉得可惜，没关系，小米特别为广大马虎的小伙伴们推出了超值的&rdquo;意外保障计划&ldquo;，购买此服务的小伙伴们，可享受原厂保修范围外的意外损坏保修，在一年有效期内，由于意外坠落、挤压、碰撞或进液导致设备受损且又无法正常使用，都可以获得免费维修服务。<br />\r\n<br />\r\n<strong>意外保价格：</strong><br />\r\n<br />\r\n红米手机2/红米手机2A/红米Note/红米Note3都只要59元；<br />\r\n小米手机4/4C/4S系列都只要99元；<br />\r\n小米note/小米5/小米MAX只要199元您就可以拥有该服务哦。<br />\r\n<br />\r\n<strong>常见的原厂保修范围外的意外手机损坏情况包括：</strong><br />\r\n<br />\r\n手机不慎进水、手机屏幕被摔破裂等。<br />\r\n您可在购买小米手机时一并选择购买该保障服务，更多介绍，</span><a href=\"http://www.mi.com/service/safe\"><span style=\"color: rgb(255, 140, 0);\">点击这里</span></a><span style=\"color: rgb(105, 105, 105);\">，前往意外保障服务页面查看详情。</span></div>',1,'','2016-07-27 18:37:58','2016-07-27 18:37:58'),(34,7,'小米云服务','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉，目前最新版本小米云服务，可以将手机上的 短信、联系人、便签、WLAN设置、通话记录、录音、音乐列表以及多看阅读等数据，同步至小米服务器，将手机上相册、APP应用备份至小米服务器。<br />\r\n<br />\r\n但是目前可以显示被同步至服务器的只有短信、联系人、便签、相册、通话记录内容，以及实现&ldquo;查找手机&rdquo;功能的应用。您可以在浏览器输入https://i.xiaomi.com进入小米云服务，或者点击</span><a href=\"https://i.xiaomi.com/\" target=\"https://support.kefu.mi.com/_blank\"><span style=\"color: rgb(255, 140, 0);\">小米云服务</span></a><span style=\"color: rgb(105, 105, 105);\">登陆页面，尽情体验。</span></div>',1,'','2016-07-27 18:37:59','2016-07-27 18:37:59'),(35,7,'信用卡分期付款','<div><ul>\r\n<li><span style=\"color: rgb(105, 105, 105);\">在小米网购物在线支付，如今可选择申请灵活的分期付款服务。目前支持招商银行、建设银行、工商银行和农业银行4家银行的信用卡及蚂蚁花呗的分期支付。</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">每期还款金额是根据你的订单估算得出的金额，实际支付数额请以银行/支付宝账单为准，银行/支付宝有权决定是否接受您的分期付款申请。</span></li>\r\n</ul>\r\n<h4><span style=\"color: rgb(169, 169, 169);\">分期付款选择及费率</span></h4>\r\n<span style=\"color: rgb(105, 105, 105);\">这4家银行的信用卡用户购买产品达600元 以上可申请分期付款服务, 订单最高限额为30000元。 银行会根据您的申请进行核实及批准。现在购买并完成支付可优享如下费率，具体支付数额以银行账单为主，请参考页面下方细则 。</span><br />\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670252286414_LdxoG.jpg\" style=\"height: 440px; width: 861px;\" /><br />\r\n<h4><span style=\"color: rgb(169, 169, 169);\">如何申请分期付款</span></h4>\r\n<br />\r\n<img src=\"//i3.mifile.cn/a4/cms_14670251354219_wUQdk.jpg\" style=\"height: 339px; width: 861px;border: 1px solid #dfdfdf;\" /><br />\r\n<br />\r\n<span style=\"color: rgb(169, 169, 169);\"><strong>分期付款基本条款</strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">Q1. 我可以申请分期的订单金额是多少？<br />\r\n<br />\r\n当您需支付的订单金额在600元（含600元） 至8000元（含8000元）范围，您可选择分期付款支付。<br />\r\n<br />\r\nQ2. 小米网提供的分期付款的期数是多少？<br />\r\n<br />\r\n目前，小米网与招商银行、中国建设银行、中国工商银行及中国农业银行合作，提供3期、6期、12期三种分期。<br />\r\n<br />\r\nQ3.办理完分期付款业务后，我的可用额度是多少？<br />\r\n<br />\r\n这4家银行信用卡网上分期付款以分期付款总金额占用您的信用额度，因此，您的可用额度需扣除分期总金额,随着每月分期还款，您的可用额度也将逐步恢复。<br />\r\n<br />\r\nQ4.取消订单退款怎么办理？会扣手续费吗？如果部分退款手续费如何收取？<br />\r\n<br />\r\n您可通过在线申请退货或者致电客服400-100-5678申请。您的申请通过审核后，小米将会将订单全款返还给招商银行，银行会及时向您发放，这个流程会在15日内完成。如有其他意外情况将单独处理。当您退货商品时，小米不会扣除您的手续费，分期付款产生的手续费为银行所收取和返还。</span><br />\r\n<br />\r\n<span style=\"color: rgb(169, 169, 169);\"><strong>全单退款：</strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">当您全单退货分期付款商品时，则退还已收取的本金和手续费，后续不再出账单。 例如：以招商银行举例来说，订单全额为2000元分3期，并已出第1期账单金额为666.66元，手续费为26元。若此时办理全额退款，则持卡人退还666.66元和26元手续费，不再出第2、第3期账单。小米将在受理退款后将2000元返还给招商银行，银行会退回26元并将及时向您的账户发放。</span><br />\r\n<br />\r\n<span style=\"color: rgb(169, 169, 169);\"><strong>部分退款：</strong></span><br />\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">当您部分退货分期付款商品时，则已收取的本金和手续费按比例退还，未收取的按后续实际的分期金额和手续费收取。 例如：以招商银行为例说，订单全额为2000元分3期，若此时办理1000元退款，则持卡人退还333.33元和13元手续费，后续第2期出333.33元和13元手续费，第3期出333.34元和13元手续费。小米将在受理退款后将1000元返还给招商银行，银行会退回13元并及时向您的账户发放。<br />\r\n<br />\r\n5. 网上分期也送招商银行消费积分么？<br />\r\n<br />\r\n是。使用招商银行网上分期同样可以参加永久积分计划，根据每月单期入账金额计算，逐月累积信用卡积分。<br />\r\n<br />\r\n6. 退款后多久到账？<br />\r\n<br />\r\n当小米成功受理您的退款申请后，15个工作日内将到账您的信用卡账户。<br />\r\n<br />\r\n7. 为什么我的分期付款会被银行拒绝？<br />\r\n<br />\r\n在您的信用卡可以正常使用(如申请网上分期须开通信用卡网上支付功能，且所购产品金额不超过网上交易限额)情况下，最常见的被拒绝原因是您的当前可用额度已经不足以支付分期付款的总金额。具体的拒绝原因，您可以拨打信用卡24小时客服热线咨询，招商银行：800-820-5555，建设银行：400-820-0588，工商银行：95588，农业银行：400-669-5599。<br />\r\n<br />\r\n8. 我购买的总金额不能被分期的期数整除时怎么办？<br />\r\n<br />\r\n每一期的账单金额为 总金额/期数 ，若遇到除不尽的，会在最后一期收取完整。 如办理2000元分3期，则第1、第2期出666.66元，第3期出666.68元。</span></div>',1,'','2016-07-27 18:37:59','2016-07-27 18:37:59'),(36,7,'举报假小米','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉感谢您来到这里，如果没有猜错的话，您一定是遇到假店铺或是假产品了，感谢您在气愤之余，愿意与我们一起维护小米的荣誉，下面需要借用您几分钟的宝贵时间</span><a href=\"http://jubao.order.xiaomi.com/\"><span style=\"color: rgb(255, 140, 0);\">进行登记</span></a><span style=\"color: rgb(105, 105, 105);\">，我们会认真核实您反馈的情况，一经查实，严肃处理。</span></div>',1,'','2016-07-27 18:37:59','2016-07-27 18:37:59'),(37,8,'虚拟运营商','<div><span style=\"color: rgb(105, 105, 105);\">小米移动为小米公司为方便用户更好的选择更合适自己的电话卡资费套餐提供的通信服务的品牌（实体产品为：手机号卡、sim卡），手机号码均为170开头的手机号码，目前小米移动有&ldquo;任我行&rdquo;和&ldquo;吃到饱&rdquo;两个子品牌（采用联通/电信制式，暂无移动制式手机卡），目前小米移动客服号码为4009223838，拨打该电话收取正常通话费用（市话费）。小米移动热线客服服务时间为7*24小时，您随时遇到问题随时拨打客服电话，您可以点击</span><a href=\"http://www.mi.com/mimobile/\"><span style=\"color: rgb(255, 140, 0);\">小米移动</span></a><span style=\"color: rgb(105, 105, 105);\">了解详情。</span><embed height=\"0\" id=\"xunlei_com_thunder_helper_plugin_d462f475-c18e-46be-bd10-327458d045bd\" type=\"application/thunder_download_plugin\" width=\"0\"></embed><embed height=\"0\" id=\"xunlei_com_thunder_helper_plugin_d462f475-c18e-46be-bd10-327458d045bd\" type=\"application/thunder_download_plugin\" width=\"0\"></embed></div>',1,'','2016-07-27 18:37:59','2016-07-27 18:37:59'),(38,8,'电话加油包','<div><span style=\"color: rgb(105, 105, 105);\"><strong><span style=\"font-size: 14px;\">一、使用及介绍（1）</span></strong><br />\r\n<br />\r\n1、设置路径：设置-&gt;系统应用-&gt;电话-&gt;小米电话加油包。<br />\r\n<br />\r\n2、首次使用需要充值，有四个套餐可选择：3.5元加油包（50分钟国内），13.5元加油包（200分钟国内）,32元加油包（500分钟国内），60元加油包（1000分钟国内）；可用于国际通话，每6分钟国内时长折合1分钟国际时长。除了中国大陆其他地区均属于是国际，如：香港，台湾，美国。充值的加油包没有期限，使用完为止。<br />\r\n<br />\r\n3、使用记录、购买明细：通话时长不足一分钟也按一分钟计算。<br />\r\n<br />\r\n4、无需电话加油包拨打的号码：添加的号码，在拨打电话时使用的是普通拨号。<br />\r\n<br />\r\n5、不支持拨打服务号码和短号码（短号码：是运营商（移动、联通、电信）提供的一种集团优惠服务，加入某个特定集团，该集团成员之间相互拨打电话不需要拨11位手机号，直接拨打短号码（如：5404）就可打通该集团另一个成员的电话）。<br />\r\n<br />\r\n&nbsp;6、例如拨打北京的固话，需要在默认区号输入：010。<br />\r\n<br />\r\n<strong><span style=\"font-size: 14px;\">二、使用及介绍（2）</span></strong><br />\r\n<br />\r\n1、若您之前系统有小米加油包，进行刷机或恢复出厂后没有该功能，可以进行以下操作：黄页-&gt;充话费-&gt;点击&ldquo;0.05元/每分钟&rdquo;按钮，只要点击了上述按钮，即可在拨号盘设置中找到小米电话加油包。</span></div>',1,'','2016-07-27 18:38:00','2016-07-27 18:38:00'),(39,8,'小米金融','<div><span style=\"color: rgb(105, 105, 105);\">一、小米基金宝<br />\r\n<br />\r\n1、 小米基金宝是什么？<br />\r\n<br />\r\n小米基金宝是小米金融推出的一项基金类理财产品，目前精选两款指数基金。指数基金就是以特定指数（如易方达创业板ETF联接，易方达沪深300量化增强证券投资基金）为标的指数，并以该指数的成分股为投资对象，通过购买该指数的全部或者部分成分股构建投资组合，以追踪标的指数表现的基金产品。通常而言，指数基金以减小跟踪误差为目的，使投资组合的变动趋势与标的指数相一致，以取得与标的指数大致相同的收益率。<br />\r\n<br />\r\n2、 指数基金的分类<br />\r\n<br />\r\n目前市场上的指数基金按照基金管理人对其的主动管理程度，可分为完全复制型和增强型两类指数基金。<br />\r\n完全复制型：这种指数基金力求按照标的指数的成分和权重进行配置，其目标是最大限度地减小与标的指数的跟踪误差，如易方达创业板ETF联接。<br />\r\n增强型：这种指数基金在将大部分资产按照标的指数权重配置的基础上，也用一部分资产进行主动的投资。其目标为在紧密跟踪标的指数的同时获得高于标的指数的收益。如易方达沪深300量化增强证券投资基金。<br />\r\n<br />\r\n3、 指数基金的风险如何？<br />\r\n<br />\r\n指数型基金属于证券投资基金中风险收益偏高的品种。首先，指数基金短期波动大，对于短线操作来说风险偏大。其次，在任何市场下，指数基金都是高仓位操作，无法通过基金经理的操作来规避股市的风险。<br />\r\n<br />\r\n4、 其他问题处理方案<br />\r\n<br />\r\n若有用户咨询其他关于基金宝问题，可以建议用户查看小米金融-什么是基金宝，若有FAQ无法解答的问题，优先建议用户联系易方达客服：400-881-8088工作时间周一至周日8：30-22：00（法定节假日除外）<br />\r\n<br />\r\n二、活期宝<br />\r\n<br />\r\n1、 小米活期宝是什么？<br />\r\n<br />\r\n小米活期宝是小米金融推出的一项便捷理财业务，用户把资金转入小米活期宝，实际上申购了一款易方达基金公司旗下&ldquo;天天理财货币基金A（000009）&rdquo;的货币基金。<br />\r\n小米活期宝对应的是易方达的天天理财基金，为货币市场基金，属于证券投资基金中风险极低的品种。从天天理财货币基金成立以来的数据来看，每天都有收益，未发生过亏损。<br />\r\n<br />\r\n2、 小米活期宝的优势<br />\r\n<br />\r\n买入小米活期宝的资金，不仅可以获得收益，而且还能随时赎回，非常灵活便捷。<br />\r\n<br />\r\n3、 货币基金安全吗？<br />\r\n<br />\r\n目前，小米活期宝购买的货币基金是风险最小的投资产品，主要投资于低风险，高流动性的短期固定收益品种。从历史数据来看收益稳定，风险极小。<br />\r\n<br />\r\n4、 小米活期宝收其他手续费用吗？<br />\r\n<br />\r\n目前，小米活期宝开户、买入、赎回都不收取任何手续费，请您放心使用，如果有相关变动，我们会提前在网站上通知。<br />\r\n<br />\r\n5、 小米活期宝开户支持的证件类型<br />\r\n<br />\r\n仅支持个人通过身份证开户<br />\r\n<br />\r\n6、 可以开立几个小米活期宝账户？<br />\r\n<br />\r\n一个身份证仅支持开立1个小米活期宝账户<br />\r\n<br />\r\n7、 小米活期宝开户的年龄要求<br />\r\n<br />\r\n您必须年满18周岁<br />\r\n<br />\r\n8、 开户时支持绑定什么银行卡？<br />\r\n<br />\r\n工行，中行，建行，招行，华夏银行，光大银行，上海银行，平安银行的借记卡<br />\r\n<br />\r\n9、 如何更换开户绑定的银行卡<br />\r\n<br />\r\n目前暂不支持，后期会支持<br />\r\n<br />\r\n10、如何操作小米金融APP买入小米活期宝<br />\r\n<br />\r\n操作步骤：<br />\r\n<br />\r\n（1）打开小米金融APP；<br />\r\n（2）首页找到活期宝产品介绍，点击&ldquo;购买&rdquo;；<br />\r\n（3）输入您想购买的金额，点击&ldquo;立即购买&rdquo;；<br />\r\n（4）输入相关银行卡信息，开通银行卡支付；<br />\r\n（5）完成购买。<br />\r\n<br />\r\n11、如何查看小米活期宝金额明细<br />\r\n<br />\r\n操作步骤：<br />\r\n<br />\r\n（1）打卡小米金融APP；<br />\r\n（2）首页找到活期宝产品介绍，点击&ldquo;活期宝&rdquo;；<br />\r\n（3）进入活期宝详情页面，点击&ldquo;历史记录&rdquo;，查看购买记录。<br />\r\n此处需要手机操作截图，告诉用户如何操作<br />\r\n<br />\r\n12、小米活期宝买入相关说明<br />\r\n<br />\r\n（1）支持用银行卡；<br />\r\n（2）不支持米币；<br />\r\n（3）不支持小米钱包余额；<br />\r\n（4）买入后不支持退款，只能赎回；<br />\r\n（5）买入后需要基金公司确认份额后才会开始计算收益，交易日15:00点前买入，第二个交易日生效；交易日15:00点后需要第三个交易日生效；<br />\r\n<br />\r\n13、小米活期宝买入后，何时可以赎回？<br />\r\n<br />\r\n买入成功后，随时可以赎回。<br />\r\n注：若因为网络或银行原因，未及时反馈扣款结果，客户将无法立刻提交该笔份额的取现申请。须在到帐后，客户才可进行赎回。<br />\r\n<br />\r\n14、小米活期宝赎回到账时间<br />\r\n<br />\r\n（1）快速赎回：实时到账。（凌晨0点&mdash;2点的快速赎回现款项将在2点后划出，其余时间提交的快速赎回，实时到账）<br />\r\n（2）标准赎回：T 1个日到账，即第二个交易日到账。<br />\r\n<br />\r\n15、小米活期宝赎回未到账怎么办<br />\r\n<br />\r\n请先不要着急，可能由于网络延时的原因未能及时入账，我们与银行工作人员会加急处理，请您关注银行卡资金明细。如果还想查看具体的进度，您可以在历史记录中查询。<br />\r\n温馨提示：目前不是所有银行进出帐都有短信通知，您可以通过银行明细来确认是否到账。<br />\r\n<br />\r\n16、小米活期宝赎回每日限额<br />\r\n<br />\r\n（1）快速赎回：每自然日单最多3次，总额度不超过6万元；<br />\r\n（2）标准赎回：无次数及金额限制。<br />\r\n<br />\r\n17、赎回后，从何时起不再享有收益？<br />\r\n<br />\r\n（1）快速赎回：自您提交快速赎回之日（自然日，含当日）起，将不再享有相应基金份额的收益。<br />\r\n（2）普通赎回：T日普通取现，T 1交易日起不再享有相应部分基金份额的收益。<br />\r\n<br />\r\n18、赎回时，能否赎回到别的银行卡<br />\r\n<br />\r\n目前只支持单卡进出。<br />\r\n<br />\r\n19、小米活期宝收益开始计算、产生、发放时间<br />\r\n<br />\r\n买入到产生收益共三个环节，【买入】--【确认份额】（确认后计算收益）--【收益发放】<br />\r\nT日买入，T 1个交易日起开始享有小米活期宝收益。</span><br />\r\n<br />\r\n<table border=\"2\" bordercolor=\"#000000\" cellpadding=\"0\" cellspacing=\"0\">\r\n<tbody>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">申购时间</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">首次计收益时间</span></td>\r\n	</tr>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周一15:00至周二15:00</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周三</span></td>\r\n	</tr>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周二15:00至周三15:00</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周四</span></td>\r\n	</tr>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周三15:00至周四15:00</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周五（可享受周六周日收益）</span></td>\r\n	</tr>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周四15:00至周五15:00</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">下周一（不享受周六周日收益）</span></td>\r\n	</tr>\r\n	<tr>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">周五15:00至下周一15:00</span></td>\r\n	<td><span style=\"color: rgb(105, 105, 105);\">下周二</span></td>\r\n	</tr>\r\n</tbody>\r\n</table>\r\n<br />\r\n<span style=\"color: rgb(105, 105, 105);\">温馨提示：仅在交易日确认份额（不包含节假日和周末），收益是每天显示。但若存入金额低于100元，收益金额过低将不会展示。<br />\r\n<br />\r\n20、买入后，何时可以查到收益？<br />\r\n<br />\r\nT日申购，T 1日起开始享有收益，T 2日凌晨可查询到T 1日的收益。<br />\r\n<br />\r\n21、小米活期宝收益的计算公式<br />\r\n<br />\r\n基金公司每天都会公布【万份收益】<br />\r\n实际收益=【万份收益】*（【小米活期宝确认金额】/10000）<br />\r\n举例：买入2万元小米活期宝，开始计算收益后，如果当天公布的万份收益是1.8064，那么当天的实际收益就是2*1.8064=3.6128元。<br />\r\n<br />\r\n22、小米活期宝节假日有收益吗<br />\r\n<br />\r\n买入小米活期宝之后的第二个交易日基金公司进行份额的确认，对已确认的份额，不再区分是否节假日，均会产生收益。<br />\r\n<br />\r\n23、小米活期宝的收益为什么有波动<br />\r\n<br />\r\n买入小米活期宝的钱是购买一款货币基金的，货币基金主要投资于银行协议存款以及信用级别极高的债券资产，其收益率的波动取决于银行协议存款利率和债券资产价格的高低。但是收益总额一直是在增长的，只是每天增加的幅度不同而已。<br />\r\n<br />\r\n24、其他问题处理方案<br />\r\n<br />\r\n若有用户咨询其他关于活期宝问题，可以建议用户联系易方达客服：400-881-8088工作时间周一至周日8：30-22：00（法定节假日除外）或致电小米客服400-100-5678选择6（热线同学可直接转接至金融组），进入小米金融进行咨询<br />\r\n<br />\r\n三、小米信用分<br />\r\n<br />\r\n1、什么是小米信用分<br />\r\n<br />\r\n小米信用分是小米金融推出的一款对小米手机用户信用评级的产品，可以通过小米信用分来评估小米用户在小米的信用记录，根据不同的信用分等级，对应的有不同的权益。<br />\r\n<br />\r\n2、小米信用分有什么用<br />\r\n<br />\r\n目前小米信用分区分了不同的贷款额度，后续将推出一系列针对信用分的权益计划。<br />\r\n<br />\r\n3、如何提升我的小米信用分<br />\r\n<br />\r\n完成信用分任务，可以对应的提升信用分数。持续保持良好的手机使用习惯，保证小米贷款以及其他的贷款、信用卡正常归还，可以逐步累计您的信用分数。<br />\r\n<br />\r\n4、什么事情会降低信用分<br />\r\n<br />\r\n当出现手机使用异常、小米贷款逾期还款、其他贷款逾期还款、提交虚假材料等情况时，可能会影响您的信用分数<br />\r\n<br />\r\n5、信用分如何变化<br />\r\n<br />\r\n您完成信用成长任务时，信用分会实时变化。另外我们会针对您的个人信息、使用情况每月变化一次。<br />\r\n<br />\r\n6、信用分和额度有影响吗<br />\r\n<br />\r\n信用分代表的是用户整体的信用评级，对额度有一定的影响，但是不完全决定您的额度。</span></div>',1,'','2016-07-27 18:38:00','2016-07-27 18:38:00'),(40,9,'身边的小米之家','<div><span style=\"color: rgb(105, 105, 105);\">嗨！亲，您是来寻找小米之家的信息的么？<br />\r\n嗯！我猜是的，瞬间感觉自己聪明绝顶`(*&cap;_&cap;*)&prime;<br />\r\n呐！您说，我要不要告诉您，查看小米之家的详细信息需要</span><a href=\"http://www.mi.com/c/xiaomizhijia/\" target=\"_blank\"><span style=\"color: rgb(255, 140, 0);\">点击这里</span></a><span style=\"color: rgb(105, 105, 105);\">呢？<br />\r\n呐！您说，我要不要告诉您，如果您所在城市没有米家，您也可以到当地授权维修点进行售后</span><a href=\"http://www.mi.com/c/service/poststation/\" target=\"_blank\"><span style=\"color: rgb(255, 140, 0);\">点击这里</span></a><span style=\"color: rgb(105, 105, 105);\">呢？<br />\r\n呐！我这么善良，忍不住要提醒您，提前预约服务会让您避免长时间排队等待哦。<br />\r\n哎！被自己的善良感动哭了&hellip;&hellip;</span></div>',1,'','2016-07-27 18:38:00','2016-07-27 18:38:00'),(41,9,'查询授权服务网点','<div><span style=\"color: rgb(105, 105, 105);\">嗨！亲，如果您想要查询授权服务网点信息您可以</span><a href=\"http://www.mi.com/static/maintainlocation/\"><span style=\"color: rgb(255, 140, 0);\">猛戳我</span></a><span style=\"color: rgb(105, 105, 105);\">，不费吹灰之力，带您快速查阅附近的网点分布，想去哪里选哪里！<br />\r\n但是，如果您的产品是电视，那人家就无能为力啦，您需要拨打400-100-5678或者咨询在线客服选择电视分类，让客服妹妹帮您进行售后处理哦。<br />\r\n<br />\r\n注：<br />\r\n&nbsp;<br />\r\n小米授权维修网点上班时间及您需要咨询的相关事宜您可以拨打您附近的维修网点电话进行咨询~</span></div>',1,'','2016-07-27 18:38:00','2016-07-27 18:38:00'),(42,9,'到店1小时快修服务','<div><p><strong><span style=\"font-size: 14px;\"><span style=\"color: rgb(105, 105, 105);\">小米之家承诺：</span></span></strong><br />\r\n&nbsp;</p>\r\n<ul>\r\n<li><span style=\"color: rgb(105, 105, 105);\">保修期内1小时修好您的手机</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">如从接待到维修完成时间超过1小时，将赠20元小米网配件现金券</span></li>\r\n<li><span style=\"color: rgb(105, 105, 105);\">配件现金券可在小米网购买配件时直接抵扣现金</span></li>\r\n<li><a href=\"http://www.mi.com/c/xiaomizhijia/\"><span style=\"color: rgb(255, 140, 0);\">戳我</span></a><span style=\"color: rgb(105, 105, 105);\">，查询距离您最近的米家信息</span></li>\r\n</ul>\r\n<p><br />\r\n<span style=\"font-size: 14px;\"><strong><span style=\"color: rgb(105, 105, 105);\">欢迎您的监督！</span></strong></span></p></div>',1,'','2016-07-27 18:38:01','2016-07-27 18:38:01'),(43,9,'查询县级受理点','<div><span style=\"color: rgb(105, 105, 105);\">亲爱的米粉朋友，为了方便您的售后，我们在县区级单位开设了受理点，负责免费帮您将需要售后的产品邮寄至小米授权服务中心，让您更便捷、更放心地享受我们的服务。<br />\r\n&nbsp;<br />\r\n目前，我们的受理点只能提供将产品邮寄至上级维修网点进行维修的服务，受理点本身是不能帮您的产品进行维修的哦。如果您已经成功办理，我们会在5个工作日内处理完毕，您可以在五日后去受理点取回您的爱机。<br />\r\n&nbsp;<br />\r\n注：<br />\r\n&nbsp;<br />\r\n目前我们的受理点只支持小米手机、小米平板、小米盒子、小米路由器产品的售后服务；<br />\r\n如果您的产品已经超出质保期，不要担心，维修网点会按照全国统一报价，联系您告知维修价格。<br />\r\n&nbsp;<br />\r\n如果您已经了解以上详情，</span><a href=\"http://www.mi.com/static/acceptance/\"><span style=\"color: rgb(255, 140, 0);\">戳我</span></a><span style=\"color: rgb(105, 105, 105);\">带您查询最近的受理点。</span></div>',1,'','2016-07-27 18:38:01','2016-07-27 18:38:01'),(44,5,'zxczxczx','<p>啊实打实大</p>',0,'','2016-07-29 09:24:16','2016-07-29 09:25:39');
