  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '帮助栏目名称',
  `pid` int(11) NOT NULL COMMENT '帮助栏目所属栏目id',
  `show` tinyint(4) NOT NULL COMMENT '帮助栏目是否显示在底部',
  `path` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL COMMENT '帮助栏目分类路径',
  `status` tinyint(4) NOT NULL COMMENT '帮助栏目显示状态',
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
